import type { Metadata } from "next";
import { ArrowUpRight } from "lucide-react";
import { Col } from "@/components/layout/Grid";
import { Section } from "@/components/layout/Section";
import { ListingHeader } from "@/components/plp/ListingHeader";
import credits from "@/data/generated/photo-credits.json";

export const metadata: Metadata = { title: "Photo credits", description: "The photographers whose Unsplash photographs appear in this prototype." };

/** One photograph placed on the site (generated by scripts/unsplash/build.mjs → src/data/generated/photo-credits.json). */
interface Credit {
  id: string;
  name: string;
  username: string;
  profile: string;
  page: string;
  alt: string;
  uses: string[];
}

const sentence = (s: string) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : "Photograph");

/** Photographers in the order of the file (already sorted by name), each with their photographs. */
function byPhotographer(list: Credit[]) {
  const out: Array<{ name: string; username: string; profile: string; photos: Credit[] }> = [];
  for (const c of list) {
    const last = out[out.length - 1];
    if (last && last.username === c.username && last.name === c.name) last.photos.push(c);
    else out.push({ name: c.name, username: c.username, profile: c.profile, photos: [c] });
  }
  return out;
}

const ext = "link-u inline-flex items-center gap-1.5 text-[14px] font-medium text-ink";

export default function CreditsPage() {
  const list = credits as Credit[];
  const people = byPhotographer(list);
  return (
    <>
      <ListingHeader
        crumbs={[{ name: "Home", href: "/" }, { name: "Photo credits" }]}
        title="Photo credits"
        intro={
          list.length
            ? "The photographs in this prototype are from Unsplash and are used under the Unsplash License. Thank you to the photographers below."
            : "This prototype currently shows only the studio photographs supplied by its owner. Photographs from Unsplash, once added, are credited here."
        }
      />
      <Section y="none" className="pb-[var(--section-y)]">
        {list.length > 0 && (
          <div className="border-t border-line pt-6">
            <p className="text-[13px] text-ink-3">
              <span className="tabular-nums text-ink">{list.length}</span> photographs · <span className="tabular-nums text-ink">{people.length}</span> photographers
            </p>
            <div className="mt-6 border-b border-line">
              {people.map((p) => (
                <section key={`${p.username}-${p.name}`} aria-label={p.name} className="grid-main gap-y-4 border-t border-ink py-6 first:border-t-0 sm:py-8">
                  <Col span={{ base: 4, sm: 12, lg: 4 }}>
                    <h2 className="display-sm">{p.name}</h2>
                    {p.profile && (
                      <a href={p.profile} target="_blank" rel="noopener noreferrer" className={`${ext} mt-2`}>
                        {p.username ? `@${p.username}` : "Profile"} on Unsplash <ArrowUpRight size={14} aria-hidden />
                      </a>
                    )}
                  </Col>
                  <Col span={{ base: 4, sm: 12, lg: 8 }} as="ul" className="space-y-5">
                    {p.photos.map((c) => (
                      <li key={c.id} className="text-[14px] leading-relaxed">
                        <p className="text-ink">{sentence(c.alt)}</p>
                        <p className="mt-1 text-ink-3">Used in {c.uses.join(" · ")}</p>
                        <a href={c.page} target="_blank" rel="noopener noreferrer" className={`${ext} mt-2`}>
                          View photograph <ArrowUpRight size={14} aria-hidden />
                        </a>
                      </li>
                    ))}
                  </Col>
                </section>
              ))}
            </div>
          </div>
        )}
      </Section>
    </>
  );
}
